mapper.select:
SELECT s.item_id, s.item_title, s.item_content, s.created_at, s.item_price, s.category, i.image_url, i.PQ_CODE, i.EMBEDDING_VALUE, i.DETECTED_CLASS FROM shop_board s LEFT JOIN image_info i ON s.item_id = i.item_id WHERE s.item_id = #{id}
order by DECODE(i.image_uuid, #{imgUuid}, 1, 2), i.image_uuid ASC
order by i.image_uuid ASC

SELECT * FROM (
    SELECT T.*, ROWNUM AS rn FROM (
    SELECT item_id,
    item_title,
    CREATED_AT
FROM shop_board
ORDER BY item_id desc
) T WHERE ROWNUM <= (#{offset}+1) * #{size}
) WHERE rn > #{offset}  * #{size}

  SELECT * FROM (
    SELECT T.*, ROWNUM AS rn FROM (
      SELECT s.item_id,
         s.item_title,
         s.item_price,
         i.image_url
          FROM shop_board s
              INNER JOIN (
              SELECT item_id, image_url
              FROM (
              SELECT item_id,
              image_url,
              ROW_NUMBER() OVER (PARTITION BY item_id ORDER BY image_uuid asc) rn
              FROM image_info
              WHERE image_url IS NOT NULL
              )
              WHERE rn = 1
              ) i ON s.item_id = i.item_id
          WHERE 1=1

              AND s.CATEGORY = #{category}

          ORDER BY s.item_id DESC
      ) T WHERE ROWNUM <= (#{offset}+1) * #{size}
) WHERE rn > #{offset} * #{size}
